import React from 'react';

interface MatrixInputProps {
    n: number;
    matrix: number[][];
    vector: number[];
    onChange: (matrix: number[][], vector: number[]) => void;
}

export const MatrixInput: React.FC<MatrixInputProps> = ({
                                                            n, matrix, vector, onChange
                                                        }) => {
    const handleMatrixChange = (i: number, j: number, value: string) => {
        const newMatrix = matrix.map(row => [...row]);
        newMatrix[i][j] = value === '' ? 0 : parseFloat(value) || 0;
        onChange(newMatrix, vector);
    };

    const handleVectorChange = (i: number, value: string) => {
        const newVector = [...vector];
        newVector[i] = value === '' ? 0 : parseFloat(value) || 0;
        onChange(matrix, newVector);
    };

    const getDisplayValue = (value: number): string => {
        return value === 0 ? '' : value.toString();
    };

    // Определяем ширину ячейки в зависимости от n
    const getCellWidth = () => {
        if (n <= 5) return 'w-24'; // фиксированная ширина
        if (n <= 8) return 'w-20';
        if (n <= 10) return 'w-16';
        return 'w-14'; // для больших матриц
    };

    return (
        <div className="space-y-6">
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                    Матрица коэффициентов A:
                </label>
                {/* Контейнер с горизонтальным скроллом */}
                <div className="overflow-x-auto pb-4">
                    <div className="inline-block min-w-full">
                        <div
                            className="grid gap-2"
                            style={{ gridTemplateColumns: `repeat(${n}, minmax(${n <= 8 ? '80px' : '70px'}, 1fr))` }}
                        >
                            {Array.from({ length: n }).map((_, i) =>
                                Array.from({ length: n }).map((_, j) => (
                                    <input
                                        key={`a${i}${j}`}
                                        type="number"
                                        value={getDisplayValue(matrix[i]?.[j] ?? 0)}
                                        onChange={(e) => handleMatrixChange(i, j, e.target.value)}
                                        className={`${getCellWidth()} px-2 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 text-center text-sm`}
                                        step="any"
                                        placeholder={`a${i+1}${j+1}`}
                                    />
                                ))
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                    Вектор правой части b:
                </label>
                <div className="overflow-x-auto pb-2">
                    <div className="inline-block min-w-full">
                        <div
                            className="grid gap-2"
                            style={{ gridTemplateColumns: `repeat(${n}, minmax(${n <= 8 ? '80px' : '70px'}, 1fr))` }}
                        >
                            {Array.from({ length: n }).map((_, i) => (
                                <input
                                    key={`b${i}`}
                                    type="number"
                                    value={getDisplayValue(vector[i] ?? 0)}
                                    onChange={(e) => handleVectorChange(i, e.target.value)}
                                    className={`${getCellWidth()} px-2 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 text-center text-sm`}
                                    step="any"
                                    placeholder={`b${i+1}`}
                                />
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {/* Подсказка для больших матриц */}
            {n > 8 && (
                <p className="text-xs text-gray-500 italic flex items-center gap-1">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" />
                    </svg>
                    Прокручивайте горизонтально для просмотра всех элементов
                </p>
            )}
        </div>
    );
};
